python3 << 'EOF'
import json
emp = json.load(open('DATA/metadata/employee.json'))
d = json.load(open('DATA/products/CoachForce.json'))

# Find all employees with the relevant names
target_names = ['George Jones', 'Charlie Smith', 'Ian Garcia', 'Fiona Martinez', 'Ian Brown']

# Get all slack users
slack_users = set()
for msg in d['slack']:
    user = msg['Message']['User']['userId']
    if user.startswith('eid_'):
        slack_users.add(user)

# Also PR users
pr_users = set()
for pr in d['prs']:
    user = pr.get('user', {}).get('login', '')
    if user.startswith('eid_'):
        pr_users.add(user)
    for r in pr.get('reviews', []):
        u = r.get('user', {}).get('login', '')
        if u.startswith('eid_'):
            pr_users.add(u)

# Also meeting participants
mt_participants = set()
for mt in d['meeting_transcripts']:
    for p in mt.get('participants', []):
        mt_participants.add(p)

# Look up matching employees for each name
print('Looking up target names in employee directory:')
for name in target_names:
    matching_eids = []
    for eid, rec in emp.items():
        if rec['name'] == name:
            matching_eids.append((eid, rec['role']))
    print(f"\n{name}:")
    for eid, role in matching_eids:
        in_slack = eid in slack_users
        in_pr = eid in pr_users
        in_mt = eid in mt_participants
        flags = []
        if in_slack: flags.append('slack')
        if in_pr: flags.append('pr')
        if in_mt: flags.append('mt')
        print(f"  {eid} ({role}) [{', '.join(flags) if flags else ''}]")
EOF

