python3 << 'EOF'
import json
emp = json.load(open('DATA/metadata/employee.json'))
d = json.load(open('DATA/products/CoachForce.json'))

# Get all employee IDs from coachforce.json (across slack, prs, mt participants)
all_eids = set()
for msg in d['slack']:
    if msg['Message']['User']['userId'].startswith('eid_'):
        all_eids.add(msg['Message']['User']['userId'])
for pr in d['prs']:
    if pr.get('user', {}).get('login', '').startswith('eid_'):
        all_eids.add(pr['user']['login'])
    for r in pr.get('reviews', []):
        u = r.get('user', {}).get('login', '')
        if u.startswith('eid_'):
            all_eids.add(u)
for mt in d['meeting_transcripts']:
    for p in mt.get('participants', []):
        all_eids.add(p)

# Now look up George Jones and Charlie Smith that are in all_eids
print('George Jones with CoFoAIX involvement:')
for eid, rec in emp.items():
    if rec['name'] == 'George Jones' and eid in all_eids:
        print(f"  {eid} ({rec['role']})")

print('\nCharlie Smith with CoFoAIX involvement:')
for eid, rec in emp.items():
    if rec['name'] == 'Charlie Smith' and eid in all_eids:
        print(f"  {eid} ({rec['role']})")

# Now check all George Jones and Charlie Smith in CoachForce.json with their roles in meetings
print('\nAll George Jones / Charlie Smith from CoachForce.json:')
target_names = ['George Jones', 'Charlie Smith']
for eid, rec in emp.items():
    if rec['name'] in target_names and eid in all_eids:
        # Check if in mt participants
        in_mts = []
        for mt in d['meeting_transcripts']:
            if eid in mt.get('participants', []):
                in_mts.append(mt['id'])
        print(f"  {eid} ({rec['name']}, {rec['role']}) - in MTs: {in_mts}")
EOF

