import json
import os

# Check if PersonalizeForce competitor info exists in any other product files
for fname in sorted(os.listdir('DATA/products')):
    if fname.endswith('.json') and fname != 'PersonalizeForce.json':
        path = f'DATA/products/{fname}'
        try:
            d = json.load(open(path))
        except:
            continue
        for msg in d.get('slack', []):
            text = msg.get('Message', {}).get('User', {}).get('text', '')
            if any(kw in text for kw in ['PersonaAI', 'SmartSuggest', 'TailorAI']) and 'demo' in text.lower():
                print(f"{fname}: {text[:200]}")
EOF

